import React, { useEffect, useState } from 'react';
import { fetchCustomerById, fetchInteractionsByCustomerId } from '../utils/api';
import AddInteractionForm from './AddInteractionForm';
import './CustomerDetails.css';

export default function CustomerDetails({ customerId, onBack }) {
  const [customer, setCustomer] = useState(null);
  const [interactions, setInteractions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!customerId) {
      setError('Invalid customer ID');
      setLoading(false);
      return;
    }
    console.log(customerId)
    setLoading(true);
    setError('');
    fetchCustomerById(customerId)
      .then(data => {
        setCustomer(data);
        setError('');
        setLoading(false);
        return fetchInteractionsByCustomerId(customerId);
      })
      .then(data => setInteractions(data))
      .catch(() => {
        setError('Customer not found');
        setCustomer(null);
        setLoading(false);
      });
  }, [customerId]);

  if (loading) return <div>Loading details...</div>;

  if (error) return (
    <div style={{ margin: '2rem' }}>
      <button onClick={onBack}>Back to List</button>
      <div style={{ color: 'red', marginTop: '1rem' }}>{error}</div>
    </div>
  );

  if (!customer) return null;

  return (
    <div className="customer-details">
      <button onClick={onBack} style={{ marginBottom: "1.5rem" }}>Back to List</button>
      <h2>Customer Details</h2>
      <div>
        <strong>ID:</strong> {customer.id}<br/>
        <strong>Name:</strong> {customer.firstName} {customer.lastName}<br/>
        <strong>Email:</strong> {customer.email}<br/>
        <strong>Phone:</strong> {customer.phoneNumber}<br/>
        <strong>Type:</strong> {customer.customerType}<br/>
        <strong>Registration Date:</strong> {customer.registrationDate}
      </div>
      <h3>Interactions</h3>
      {interactions.length === 0 ? <div>No interactions.</div> :
        <table>
          <thead>
            <tr>
              <th>ID</th>
              <th>Type</th>
              <th>Date</th>
              <th>Description</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {interactions.map(i => (
              <tr key={i.id}>
                <td>{i.id}</td>
                <td>{i.interactionType}</td>
                <td>{i.interactionDate?.replace('T',' ')}</td>
                <td>{i.description}</td>
                <td>{i.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      }
      <h4>Add Interaction</h4>
      <AddInteractionForm
        customerId={customer.id}
        onCreate={() => {
          fetchInteractionsByCustomerId(customer.id)
            .then(data => setInteractions(data));
        }}
      />
    </div>
  );
}
